INSERT INTO "Actividad" ("nivelId", "clave", "titulo", "descripcion", "objetivo", "minutos", "juego", "reglas", "ejemplo", "orden") VALUES ((SELECT "id" FROM "Nivel" WHERE "seccion" = '1' AND "clave" = '3'), '1', 'Clasifica con la regla oculta', 'Dos grupos de fichas siguen una regla que no se dice: descúbrela y clasifica una ficha nueva.', 'Deducir la regla que separa dos grupos y aplicarla a un caso nuevo.', 3, 'clasificar', '["Verás dos grupos, A y B, con fichas ya clasificadas por una regla que no se muestra.","Compara las fichas de cada grupo para descubrir qué las separa.","Elige a qué grupo va la ficha nueva y pulsa «Comprobar». Si te equivocas pierdes una vida y se te explica la regla.","Puedes pedir hasta 3 pistas por ronda; no cuentan como error ni dan puntos."]'::jsonb, '{"secuencia":["🔴","🟠","🔵","🟣","🟡"],"resaltar":4,"respuesta":["Grupo A"],"explicacion":"A (rojo, naranja) tiene colores cálidos y B (azul, violeta) colores fríos. El amarillo es cálido, así que va con A."}'::jsonb, 0) ON CONFLICT ("nivelId", "clave") DO NOTHING;
INSERT INTO "Actividad" ("nivelId", "clave", "titulo", "descripcion", "objetivo", "minutos", "juego", "reglas", "ejemplo", "orden") VALUES ((SELECT "id" FROM "Nivel" WHERE "seccion" = '1' AND "clave" = '3'), '2', '¿Qué sobra?', 'Casi todas las palabras pertenecen a un mismo grupo: encuentra la que no encaja.', 'Nombrar la categoría de un conjunto y detectar lo que no pertenece a ella.', 3, 'sobra', '["Verás varias palabras; todas son de la misma categoría menos una.","Piensa qué nombre de grupo describe a la mayoría y toca la palabra que sobra.","Pulsa «Comprobar». Si te equivocas pierdes una vida y se te dice cuál es la categoría.","Puedes pedir hasta 3 pistas por ronda; no cuentan como error ni dan puntos."]'::jsonb, '{"secuencia":["Manzana","Pera","Silla","Uva"],"resaltar":2,"respuesta":["Silla"],"explicacion":"Manzana, pera y uva son frutas. La silla es un mueble: pertenece a otra categoría."}'::jsonb, 1) ON CONFLICT ("nivelId", "clave") DO NOTHING;
INSERT INTO "Actividad" ("nivelId", "clave", "titulo", "descripcion", "objetivo", "minutos", "juego", "reglas", "ejemplo", "orden") VALUES ((SELECT "id" FROM "Nivel" WHERE "seccion" = '1' AND "clave" = '3'), '3', 'Quédate con lo esencial', 'Un problema trae datos útiles y otros de relleno: marca solo los que necesitas para resolverlo.', 'Reducir un problema a los datos que cambian su respuesta.', 4, 'esencial', '["Verás una pregunta y una lista de datos, algunos necesarios y otros de relleno.","Por cada dato pregúntate: si lo borro, ¿todavía puedo responder?","Marca solo los esenciales y pulsa «Comprobar». Si te equivocas pierdes una vida y se te dice qué sobra o qué falta.","Puedes pedir hasta 3 pistas por ronda; no cuentan como error ni dan puntos."]'::jsonb, '{"secuencia":["Hay 2 cestas","Cada cesta tiene 5 peras","Las cestas son rojas"],"resaltar":2,"respuesta":["Hay 2 cestas","Cada cesta tiene 5 peras"],"explicacion":"Para saber cuántas peras hay basta con el número de cestas y las peras de cada una. El color no cambia la cuenta."}'::jsonb, 2) ON CONFLICT ("nivelId", "clave") DO NOTHING;
